import {recompute,mergeLedger} from './refresh.js';
import {pool} from './engine.js';
const $=id=>document.getElementById(id),fmt=(x,d=4)=>Number(x).toFixed(d);let history,analysis,ledger;
const date=s=>new Date(s+'T12:00:00Z').toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric',timeZone:'America/Toronto'});
async function load(){try{[history,analysis,ledger]=await Promise.all(['history','analysis','predictions'].map(async name=>{const r=await fetch(`data/${name}.json?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw Error(`Could not load ${name}`);return r.json()}));try{const cached=JSON.parse(localStorage.getItem('numeris-latest')||'null');if(cached&&cached.history.draws.at(-1).date>=history.draws.at(-1).date){history=cached.history;analysis=cached.analysis;ledger=mergeLedger(ledger,cached.ledger)}}catch{}render();$('error').textContent=''}catch(e){$('error').textContent=e.message+' — please retry.'}}
async function refreshLatest(){const button=$('reload');button.disabled=true;button.textContent='Refreshing…';$('refresh-status').textContent='Fetching official draw results…';$('error').textContent='';try{const r=await fetch('https://numeris-pattern-lab.vercel.app/api/latest',{cache:'no-store',signal:AbortSignal.timeout(60000)}),data=await r.json();if(!r.ok)throw Error(data.error||'Could not fetch latest data');if(data.draws.at(-1).date<history.draws.at(-1).date)throw Error('Source returned older results; existing data kept.');$('refresh-status').textContent='Recomputing model comparisons…';const updated=recompute(data,ledger);let saved=true;try{localStorage.setItem('numeris-latest',JSON.stringify(updated))}catch{saved=false}history=updated.history;analysis=updated.analysis;ledger=updated.ledger;render();$('refresh-status').textContent=`Updated ${new Date(data.fetchedAt).toLocaleTimeString('en-CA',{timeZone:'America/Toronto'})} ET · latest draw ${date(data.draws.at(-1).date)}.`+(saved?'':' Browser storage unavailable: export to retain this forecast.')}catch(e){$('error').textContent=e.message;$('refresh-status').textContent='Refresh failed. Previous results kept.'}finally{button.disabled=false;button.textContent='Refresh latest data'}}
function models(){const rows=$('era').value==='all'?analysis.allEras:analysis.summary;$('models').innerHTML=rows.map(s=>`<tr class="${s.model==='Uniform'?'baseline':''}"><td>${s.model}</td><td>${fmt(s.brier)}</td><td>${fmt(s.hits,2)}</td><td>${s.threePlus} / ${s.draws}</td><td>${fmt(s.improvement,5)} [${fmt(s.lower,5)}, ${fmt(s.upper,5)}]</td></tr>`).join('')}
function review(){const r=analysis.records.find(r=>r.date===$('review').value);if(!r)return;$('review-detail').innerHTML=`<p class="numbers">${r.actual.map(x=>String(x).padStart(2,'0')).join(' · ')}</p>`+r.scores.map(s=>`<div class="review-row"><span>${s.model}</span><span>${s.hits}/7 · Brier ${fmt(s.brier)}</span></div>`).join('')+'<p class="small">Review: compare each model’s probability loss with uniform. A higher match count on this one draw is an observation; test proposed changes on future draws.</p>'}
function render(){const f=analysis.forecast;$('target').textContent=date(f.target);$('balls').innerHTML=f.numbers.map(x=>`<span class="ball">${String(x).padStart(2,'0')}</span>`).join('');$('selected').textContent=f.model;$('reason').textContent=f.reason;$('stamp').textContent=`Recorded ${new Date(f.generatedAt).toLocaleString('en-CA',{timeZone:'America/Toronto'})} ET · v${f.engineVersion}`;$('drawcount').textContent=history.draws.length.toLocaleString();$('latest').textContent=date(history.draws.at(-1).date);$('testcount').textContent=analysis.summary[0].draws;models();
 const current=history.draws.filter(r=>pool(r.date)===52),counts=Array(52).fill(0);current.forEach(r=>r.numbers.forEach(n=>counts[n-1]++));const max=Math.max(...counts),min=Math.min(...counts);$('frequency-window').textContent=`Based on the last ${current.length} draws · ${date(current[0].date)}–${date(current.at(-1).date)} · current 1–52 pool.`;const frequencyColor=t=>{const edge=t<.5?[65,115,210]:[220,75,75],strength=Math.abs(t-.5)*2;return `rgb(${edge.map(v=>Math.round(255+(v-255)*strength)).join(',')})`};$('heatmap').innerHTML=counts.map((v,i)=>`<div class="cell" title="${i+1}: ${v} appearances in ${current.length} draws" style="background:${frequencyColor(max===min?.5:(v-min)/(max-min))};color:${max===min||Math.abs((v-min)/(max-min)-.5)<.3?'#183b35':'#fff'}">${String(i+1).padStart(2,'0')}</div>`).join('');
 $('review').innerHTML=analysis.records.slice().reverse().map(r=>`<option value="${r.date}">${date(r.date)}</option>`).join('');review();$('ledger').innerHTML=ledger.slice().reverse().map(p=>`<div class="live-row"><b>${date(p.target)} · ${p.model}</b><span>${p.numbers.join(' · ')}</span><span>${p.result?`${p.result.hits}/7 matched`:'Awaiting outcome'}</span></div>`).join('');$('sources').innerHTML=`<p>Fetched ${new Date(history.fetchedAt).toLocaleString('en-CA',{timeZone:'America/Toronto'})} ET. Coverage: ${date(history.draws[0].date)} to ${date(history.draws.at(-1).date)}. Main draws only.</p>`;
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(f.target<today)$('reason').textContent+=' This published forecast is overdue; refresh the data pipeline before using it as the next draw.';
}
$('era').addEventListener('change',models);$('review').addEventListener('change',review);$('reload').addEventListener('click',refreshLatest);$('export').addEventListener('click',()=>{if(!history)return;const blob=new Blob([JSON.stringify({history,analysis,ledger},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='numeris-experiment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});load();
